files./etc/bind/named.conf:
// auth: authoritative for test. (the lab's whole namespace)
include "/etc/bind/rndc.key";
controls { inet 127.0.0.1 port 953 allow { 127.0.0.1; } keys { "rndc-key"; }; };
options {
	directory "/var/cache/bind/netlab-case-auth";
	pid-file none;
	listen-on { 198.18.240.2; 127.0.0.1; };
	listen-on-v6 { none; };
	recursion no;
	dnssec-validation no;
	notify no;
};
logging {
	channel out { stderr; severity info; print-time yes; };
	category default { out; };
	category queries { out; };
	category lame-servers { null; };
};
zone "test" { type primary; file "/etc/bind/test.db"; };

// pubauth: authoritative for test. (the lab's whole namespace)
include "/etc/bind/rndc.key";
controls { inet 127.0.0.1 port 953 allow { 127.0.0.1; } keys { "rndc-key"; }; };
options {
	directory "/var/cache/bind/netlab-case-pubauth";
	pid-file none;
	listen-on { 198.18.240.3; 127.0.0.1; };
	listen-on-v6 { none; };
	recursion no;
	dnssec-validation no;
	notify no;
};
logging {
	channel out { stderr; severity info; print-time yes; };
	category default { out; };
	category queries { out; };
	category lame-servers { null; };
};
zone "test" { type primary; file "/etc/bind/test.db"; };

setup:
umask 077; ${BIN}/tlslab pki -dir ${EVIDENCE}/pki >/dev/null && mkdir -p ${EVIDENCE}/app ${EVIDENCE}/web && cp ${EVIDENCE}/pki/root.pem ${EVIDENCE}/app/ca-bundle.pem && chmod 644 ${EVIDENCE}/pki/*.pem ${EVIDENCE}/app/ca-bundle.pem && cat > ${EVIDENCE}/app/config.json <<'EOF'
{
  "url": "https://api/health",
  "ca_file": "${EVIDENCE}/app/ca-bundle.pem",
  "timeout": "3s"
}
EOF
cat > ${EVIDENCE}/web/nginx.conf <<'EOF'
worker_processes 1;
pid ${EVIDENCE}/web/nginx.pid;
error_log stderr warn;
events {}
http {
  access_log ${EVIDENCE}/web/access.log;
  client_body_temp_path ${EVIDENCE}/web/tmp-body;
  proxy_temp_path ${EVIDENCE}/web/tmp-proxy;
  fastcgi_temp_path ${EVIDENCE}/web/tmp-fastcgi;
  uwsgi_temp_path ${EVIDENCE}/web/tmp-uwsgi;
  scgi_temp_path ${EVIDENCE}/web/tmp-scgi;
  include ${EVIDENCE}/web/site.conf;
}
EOF
cat > ${EVIDENCE}/web/site.conf <<'EOF'
# the api service — what the server sends is chosen here
server {
  listen 198.18.240.20:443 ssl;
  server_name api.shop.test api;
  ssl_certificate     ${EVIDENCE}/pki/api-chain.pem;
  ssl_certificate_key ${EVIDENCE}/pki/api.key;
  location / { return 200 "api ok\n"; }
}
EOF
